--- a/ayid/index.html
+++ b/ayid/index.html
@@ +102 -0 @@
+<!doctype html>
+<html lang="id">
+<head>
+  <meta charset="UTF-8" />
+  <meta name="viewport" content="width=device-width, initial-scale=1.0" />
+  <meta name="description" content="Ayid — ruang digital untuk ide besar, karya bermakna, dan langkah berikutnya." />
+  <title>Ayid — Mulai dari yang Bermakna</title>
+  <style>
+    @import url('https://fonts.googleapis.com/css2?family=DM+Mono:wght@400;500&family=Plus+Jakarta+Sans:wght@400;500;600;700;800&display=swap');
+
+    :root { --ink:#11231e; --cream:#f7f3ea; --lime:#d8ff58; --coral:#ff6e52; --muted:#587068; }
+    * { box-sizing:border-box; }
+    html { scroll-behavior:smooth; }
+    body { margin:0; color:var(--ink); background:var(--cream); font-family:"Plus Jakarta Sans",sans-serif; }
+    .wrap { width:min(1120px, calc(100% - 40px)); margin:auto; }
+    nav { display:flex; justify-content:space-between; align-items:center; padding:26px 0; }
+    .brand { font-weight:800; letter-spacing:-.08em; font-size:1.85rem; text-decoration:none; color:var(--ink); }
+    .brand i { color:var(--coral); font-style:normal; }
+    nav a:not(.brand) { color:var(--ink); text-decoration:none; font-size:.9rem; font-weight:700; border-bottom:2px solid var(--ink); padding-bottom:3px; }
+    .hero { min-height:690px; padding:64px 0 80px; position:relative; overflow:hidden; }
+    .eyebrow, .label { font-family:"DM Mono",monospace; letter-spacing:.08em; text-transform:uppercase; font-size:.72rem; font-weight:500; }
+    .eyebrow { display:inline-flex; gap:9px; align-items:center; background:var(--ink); color:var(--lime); padding:9px 12px; }
+    .eyebrow::before { content:""; width:7px; height:7px; border-radius:50%; background:var(--lime); }
+    h1 { position:relative; max-width:850px; margin:27px 0 26px; font-size:clamp(3.3rem,8.4vw,7.1rem); line-height:.97; letter-spacing:-.085em; font-weight:800; z-index:1; }
+    h1 em { color:var(--coral); font-style:normal; }
+    .intro { max-width:510px; color:var(--muted); font-size:1.1rem; line-height:1.7; margin:0 0 33px; }
+    .button { display:inline-flex; align-items:center; gap:13px; background:var(--ink); color:white; text-decoration:none; padding:16px 19px; font-size:.9rem; font-weight:700; box-shadow:7px 7px 0 var(--coral); transition:transform .2s,box-shadow .2s; }
+    .button:hover { transform:translate(3px,3px); box-shadow:4px 4px 0 var(--coral); }
+    .button span { font-size:1.25rem; line-height:0; }
+    .orb { position:absolute; border-radius:50%; pointer-events:none; }
+    .orb.one { width:330px; height:330px; background:var(--lime); right:-55px; top:77px; }
+    .orb.two { width:130px; height:130px; background:var(--coral); right:24%; bottom:67px; }
+    .scribble { position:absolute; right:6%; top:128px; z-index:1; font-family:"DM Mono",monospace; font-size:.74rem; transform:rotate(10deg); }
+    .scribble::after { content:"↘"; display:block; font-size:3.5rem; margin:2px 0 0 30px; color:var(--coral); }
+    .ticker { color:var(--cream); background:var(--ink); padding:19px 0; overflow:hidden; white-space:nowrap; }
+    .ticker p { margin:0; font-family:"DM Mono",monospace; font-size:.83rem; letter-spacing:.09em; animation:run 22s linear infinite; }
+    .ticker b { color:var(--lime); font-weight:500; padding:0 28px; }
+    @keyframes run { to { transform:translateX(-50%); } }
+    section { padding:105px 0; }
+    .section-head { display:flex; justify-content:space-between; align-items:end; gap:30px; margin-bottom:40px; }
+    h2 { max-width:630px; margin:10px 0 0; font-size:clamp(2.25rem,4.7vw,4.3rem); line-height:1.04; letter-spacing:-.07em; }
+    .section-head p { max-width:250px; margin:0; color:var(--muted); line-height:1.6; font-size:.92rem; }
+    .cards { display:grid; grid-template-columns:repeat(3,1fr); gap:16px; }
+    .card { min-height:278px; padding:25px; background:#fffdf7; border:1px solid #ded8ca; display:flex; flex-direction:column; justify-content:space-between; transition:transform .2s; }
+    .card:hover { transform:translateY(-7px); }
+    .card:nth-child(2) { background:var(--lime); }
+    .card:nth-child(3) { background:var(--coral); color:#fff; border-color:var(--coral); }
+    .number { font-family:"DM Mono",monospace; font-size:.8rem; }
+    .card h3 { margin:0 0 9px; font-size:1.55rem; letter-spacing:-.055em; }
+    .card p { margin:0; line-height:1.6; font-size:.9rem; opacity:.78; }
+    .statement { background:var(--lime); }
+    .statement blockquote { max-width:970px; margin:0; font-size:clamp(2.4rem,5.6vw,5.4rem); font-weight:800; line-height:1.05; letter-spacing:-.08em; }
+    .statement cite { display:block; margin-top:25px; font-family:"DM Mono",monospace; font-style:normal; font-size:.78rem; letter-spacing:.08em; }
+    .cta { background:var(--ink); color:var(--cream); text-align:center; padding:118px 0; }
+    .cta h2 { margin:14px auto 25px; max-width:800px; }
+    .cta p { max-width:470px; margin:0 auto 35px; color:#bdd1c9; line-height:1.7; }
+    .cta .button { background:var(--lime); color:var(--ink); box-shadow:7px 7px 0 var(--coral); }
+    footer { background:var(--ink); border-top:1px solid #355047; color:#bdd1c9; padding:27px 0; font-family:"DM Mono",monospace; font-size:.72rem; }
+    footer .wrap { display:flex; justify-content:space-between; gap:20px; }
+    @media (max-width:700px) { .hero { min-height:620px; padding-top:45px; } .orb.one { width:210px; height:210px; right:-80px; top:190px; opacity:.8; } .orb.two { width:85px; height:85px; right:12%; bottom:65px; } .scribble { display:none; } .section-head { display:block; } .section-head p { margin-top:18px; } .cards { grid-template-columns:1fr; } section { padding:75px 0; } footer .wrap { flex-direction:column; } }
+  </style>
+</head>
+<body>
+  <header class="wrap">
+    <nav aria-label="Navigasi utama">
+      <a class="brand" href="#beranda">ay<i>i</i>d</a>
+      <a href="#mulai">Mulai sekarang</a>
+    </nav>
+  </header>
+
+  <main id="beranda">
+    <section class="hero wrap">
+      <span class="eyebrow">Ruang untuk bertumbuh</span>
+      <p class="scribble">ide kecil<br>juga layak hidup</p>
+      <div class="orb one"></div><div class="orb two"></div>
+      <h1>Buat hal yang <em>berarti.</em><br>Mulai hari ini.</h1>
+      <p class="intro">Ayid adalah tempat untuk merangkai gagasan, menemukan arah, lalu mengubahnya menjadi karya yang benar-benar bergerak.</p>
+      <a class="button" href="#mulai">Jelajahi Ayid <span>→</span></a>
+    </section>
+
+    <div class="ticker" aria-hidden="true"><p>BERANI MULAI <b>✦</b> TUMBUH BERSAMA <b>✦</b> BIKIN DAMPAK <b>✦</b> BERANI MULAI <b>✦</b> TUMBUH BERSAMA <b>✦</b> BIKIN DAMPAK <b>✦</b></p></div>
+
+    <section class="wrap" id="tentang">
+      <div class="section-head">
+        <div><span class="label">01 / Kenapa Ayid</span><h2>Bukan sekadar tempat memulai.</h2></div>
+        <p>Ruang yang memberi ide Anda napas, struktur, serta keberanian untuk tumbuh.</p>
+      </div>
+      <div class="cards">
+        <article class="card"><span class="number">01</span><div><h3>Temukan arah</h3><p>Rapikan yang masih berisik. Jadikan intuisi sebagai langkah yang jelas.</p></div></article>
+        <article class="card"><span class="number">02</span><div><h3>Bangun bersama</h3><p>Ide terbaik jarang lahir sendirian. Temukan energi yang membuatnya bergerak.</p></div></article>
+        <article class="card"><span class="number">03</span><div><h3>Beri dampak</h3><p>Karya yang baik tidak berhenti di layar. Ia sampai ke orang yang membutuhkan.</p></div></article>
+      </div>
+    </section>
+
+    <section class="statement"><div class="wrap"><span class="label">Catatan kecil</span><blockquote>“Tidak perlu menunggu sempurna untuk memulai sesuatu yang penting.”</blockquote><cite>— AYID / 2024</cite></div></section>
+
+    <section class="cta" id="mulai"><div class="wrap"><span class="label">Langkah pertama</span><h2>Satu ide bisa mengubah banyak hal.</h2><p>Bawa rasa ingin tahu Anda. Sisanya, mari kita rangkai bersama.</p><a class="button" href="mailto:hello@ayid.id">Mari berbicara <span>↗</span></a></div></section>
+  </main>
+
+  <footer><div class="wrap"><span>© 2024 AYID</span><span>DIBUAT UNTUK IDE YANG BERJALAN JAUH</span></div></footer>
+</body>
+</html>
